  /* compress/decompress a file */
  func handle_file(_ file : String, _ sbp : FileMetadata) {
    off_t usize, gsize;
    char  outfile[PATH_MAX];

    r.infile = file
    r.infile_total = sbp.size

    if options.dflag {
      usize = file_uncompress(file, outfile, sizeof(outfile));

      if (options.vflag && options.tflag) {
        print_test(file, usize != -1);
      }

      if (usize == -1) {
        return;
      }
      gsize = sbp->st_size;
    } else {
      gsize = file_compress(file, outfile, sizeof(outfile));
      if (gsize == -1) {
        return;
      }
      usize = sbp->st_size;
    }

    r.infile = nil
    r.infile_total = 0
    r.infile_current = 0

    if (options.vflag && !options.tflag) {
      print_verbage(file, (options.cflag) ? NULL : outfile, usize, gsize);
    }

  }

  /* this is used with -r to recursively descend directories */
  func handle_dir(_ dir : String) {
    guard let fts = try? FTSWalker(path: [dir], options: [.PHYSICAL,  .NOCHDIR], sort: nil) else {
      warn("couldn't fts_open \(dir)")
      return
    }

    for entry in fts {
      switch entry.info {
        case .D, .DP:
          continue

        case .DNR, .ERR, .NS:
          maybe_warn(entry.path)
          continue
        case .F:
          handle_file(entry.path, entry.statp!)
      }
    }
    if (errno != 0) {
      warn("error with fts_read \(dir)")
    }
  }

  /* print a ratio - size reduction as a fraction of uncompressed size */
  func print_ratio(_ inxx : UInt, _ out : UInt, _ wherex : FileDescriptor) {
/*    int percent10;  /* 10 * percent */
    off_t diff;
    char buff[8];
    int len;
*/
    var inx = inxx
    var percent10 : UInt
    var diff = inx - out/2
    if inx == 0 && out == 0 {
      percent10 = 0
    }
    else if diff < 0 {
      /*
       * Output is more than double size of input! print -99.9%
       * Quite possibly we've failed to get the original size.
       */
      percent10 = -999;
    }
    else {
      /*
       * We only need 12 bits of result from the final division,
       * so reduce the values until a 32bit division will suffice.
       */
      while inx > 0x100000 {
        diff >>= 1
        inx >>= 1
      }
      if inx != 0 {
        percent10 = (diff * 2000) / inx - 1000
      }
      else {
        percent10 = 0
      }
    }

    var buff = cFormat("%2.2d.", percent10)
    /* Move the '.' to before the last digit */
    buff = String(buff.dropLast(2) + "." + buff.dropLast().suffix(1))
    var wherexx = wherex
    print(buff.leftPad(toLength: 5), terminator: "%", to: &wherexx)
  }

  /* print compression statistics, and the new name (if there is one!) */
  func print_verbage(_ file : String?, _ nfile : String?, _ usize : UInt, _ gsize : UInt) {
    var stderr = FileDescriptor.standardError
    if let file {
      print("\(file):\(file.count < 7 ? "\t\t" : "\t")  ", terminator: "", to: &stderr)
    }
    print_ratio(usize, gsize, stderr);
    if let nfile {
      print(" -- replaced with \(nfile)", terminator: "")
    }
    print("", to: &stderr)
  }

  /* print test results */
  func print_test(_ file : String, _ ok : Bool) {
    var stderr = FileDescriptor.standardError
    if r.exit_value == 0 && !ok {
      r.exit_value = 1
    }
    print("\(file):\(file.count < 7 ? "\t\t" : "\t")  \(ok ? "OK" : "NOT OK")")
  }

  /* print a file's info ala --list */
  /* eg:
   compressed uncompressed  ratio uncompressed_name
   354841      1679360  78.8% /usr/pkgsrc/distfiles/libglade-2.0.1.tar
   */
  func print_list(_ fd : FileDescriptor, _ out : UInt, _ outfile : String, _ ts : DateTime) {
    static int first = 1;

    static off_t in_tot, out_tot;
    uint32_t crc = 0;

    off_t in = 0, rv;

    if (first) {

      if (options.vflag) {
        printf("method  crc     date  time  ");
      }

      if (!options.qflag) {
        printf("  compressed uncompressed  "
               "ratio uncompressed_name\n");
      }
    }
    first = 0;

    /* print totals? */

    if (fd == -1) {
      in = in_tot;
      out = out_tot;
    } else

    {
      /* read the last 4 bytes - this is the uncompressed size */
      rv = lseek(fd, (off_t)(-8), SEEK_END);
      if (rv != -1) {
        unsigned char buf[8];
        uint32_t usize;

        rv = read(fd, (char *)buf, sizeof(buf));
        if (rv == -1) {
          maybe_warn("read of uncompressed size");
        }
        else if (rv != sizeof(buf)) {
          maybe_warnx("read of uncompressed size");
        }

        else {
          usize = le32dec(&buf[4]);
          in = (off_t)usize;

          crc = le32dec(&buf[0]);

        }
      }
    }

    if (options.vflag && fd == -1) {
      printf("                            ");
    }
    else if (options.vflag) {
      char *date = ctime(&ts);

      /* skip the day, 1/100th second, and year */
      date += 4;
      date[12] = 0;
      printf("%5s %08x %11s ", "defla"/*XXX*/, crc, date);
    }
    in_tot += in;
    out_tot += out;

    print_list_out(out, in, outfile);
  }

  func print_list_out(_ out : UInt, _ inx : UInt, _ outfile : String) {
    printf("%12llu %12llu ", (unsigned long long)out, (unsigned long long)in);
    print_ratio(inx, out, FileDescriptor.standardOutput)
    print(" \(outfile)")
  }

